pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 newMinSum) internal {
        uint256 oldMinSum;
        try c.MinSum() returns (uint256 __r) { oldMinSum = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(newMinSum) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.MinSum() == oldMinSum);
    }

    function testFuzz_run(uint256 newMinSum) public {
        _run(newMinSum);
    }

    receive() external payable {}
}
